public class MathArrays_sortInPlace_TriageGen2Test {

    @Test
    public void testSortInPlaceIncreasing() throws DimensionMismatchException, NullArgumentException {
        double[] x = {3.0, 1.0, 2.0};
        double[] y1 = {10.0, 20.0, 30.0};
        double[] y2 = {100.0, 200.0, 300.0};

        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING, y1, y2);

        assertArrayEquals(new double[]{1.0, 2.0, 3.0}, x, 1e-10);
        assertArrayEquals(new double[]{20.0, 30.0, 10.0}, y1, 1e-10);
        assertArrayEquals(new double[]{200.0, 300.0, 100.0}, y2, 1e-10);
    }
















}

