import org.apache.commons.math3.exception.NonMonotonicSequenceException;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NullArgumentException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.fail;

public class MathArrays_sortInPlace_TriageGen2Test {













    @Test
    public void testSortInPlaceWithDuplicates() throws DimensionMismatchException, NullArgumentException {
        double[] x = {2.0, 1.0, 2.0};
        double[] y = {10.0, 20.0, 30.0};

        // Stability is not strictly guaranteed by Collections.sort for all Pair implementations, 
        // but we test the logic works with duplicates.
        MathArrays.sortInPlace(x, MathArrays.OrderDirection.INCREASING, y);

        // x becomes 1.0, 2.0, 2.0
        assertArrayEquals(new double[]{1.0, 2.0, 2.0}, x, 1e-10);

        // y must contain 10, 20, 30 in some order matching x
        // Since 2.0 appears at index 0 and 2:
        // x[0]=1.0 (orig y[1]=20.0)
        // x[1]=2.0 (orig y[0]=10.0 or y[2]=30.0)
        // x[2]=2.0 (orig y[2]=30.0 or y[0]=10.0)
        double sumY = 0;
        for(double val : y) sumY += val;
        assert(Math.abs(sumY - 60.0) < 1e-10);
    }




}

